import{_ as i,o as t,c as s,a3 as a,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const l="/bilder/schueler/foerdermassnahmen-allgemein-uebersicht.png",d="/bilder/schueler/foerdermassnahmen-allgemein-anlegen.png",m="/bilder/schueler/foerdermassnahmen-fachbezogen-anlegen.png",k=JSON.parse('{"title":"Fördermaßnahmen dokumentieren","description":"","frontmatter":{"title":"Fördermaßnahmen dokumentieren","source_pageid":317,"source_revision":3755},"headers":[],"relativePath":"schild3/schueler/foerdermassnahmen-schueler.md","filePath":"schild3/schueler/foerdermassnahmen-schueler.md"}'),h={name:"schild3/schueler/foerdermassnahmen-schueler.md"};function o(g,r,c,u,p,f){return t(),s("div",null,[...r[0]||(r[0]=[a('<h1 id="fordermaßnahmen-dokumentieren" tabindex="-1">Fördermaßnahmen dokumentieren <a class="header-anchor" href="#fordermaßnahmen-dokumentieren" aria-label="Permalink to &quot;Fördermaßnahmen dokumentieren&quot;">​</a></h1><p>Dokumentieren Sie allgemeine oder fachbezogene Förderung für den aktuellen Lernabschnitt. Halten Sie Diagnose, Absprachen, Zuständigkeiten und Zeitrahmen fest.</p><p><a href="/bilder/schueler/foerdermassnahmen-allgemein-uebersicht.png"><img src="'+l+'" alt="Übersicht über angelegte Fördermaßnahmen." loading="lazy"></a></p><p><em>Übersicht über angelegte Fördermaßnahmen.</em></p><p>Öffnen Sie <strong>Schüler ➜ Fördermaßnahmen</strong>, um bei nicht ausreichenden Leistungen die vorgesehene Förderung für den aktuellen Abschnitt zu dokumentieren.</p><p>Es gibt in SchILD-NRW zwei Möglichkeiten, wie die Fördermaßnahmen verwaltet werden können.</p><ul><li><strong>Allgemein</strong> zum aktuellen Abschnitt</li><li><strong>Fachbezogen</strong> zum aktuellen Abschnitt</li></ul><p>In beiden Fällen können bestimmte Angaben zu den Problemfeldern und Förderabsprachen eingegeben werden. Es können zuständige Personen eingegeben werden. Und es können Zeitrahmen gesetzt werden, in denen die Fördermaßnahme abgeschlossen werden soll.</p><h2 id="allgemeine-fordermaßnahmen" tabindex="-1">Allgemeine Fördermaßnahmen <a class="header-anchor" href="#allgemeine-fordermaßnahmen" aria-label="Permalink to &quot;Allgemeine Fördermaßnahmen&quot;">​</a></h2><p><a href="/bilder/schueler/foerdermassnahmen-allgemein-anlegen.png"><img src="'+d+'" alt="Eine Fördermaßnahme wird angelegt." loading="lazy"></a></p><p><em>Eine Fördermaßnahme wird angelegt.</em></p><p>Eine allgemeine Fördermaßnahme wird über den Button <strong>Allgemeine Fördermaßnahme anlegen</strong> erzeugt.</p><p>Das sich öffnende Fenster gliedert sich nun in Unterfelder.</p><p>Zuerst ist die <strong>Diagnose</strong> einzugeben und es kann zwischen <em>inhaltlichen</em>, <em>methodischen</em> und <em>Lern- und Arbeitsverhalten</em> Diagnosen differenziert werden.</p><p>Es schließen sich mit der gleichen Untergliederung die den Feldern zugeordneten <strong>Maßnahmen</strong> an.</p><p>In der dritten Feldzeile folgen die <strong>Verantwortlichkeiten</strong>, die in der Hand der <em>Schüler</em> und der <em>Eltern</em> liegen.</p><p>Schließlich lassen sich Daten zu <em>Weiteres Vorgehen&#39;</em> aufnehmen. Hier kann die <em>Dauer der Maßnahme</em> und die <em>nächste Überprüfung</em> wie <em>das nächste Beratungsgespräch</em> erfasst werden.</p><p>Ebenso lässt sich ein Haken setzen, wenn die <em>Fördermaßnahme abgeschlossen&#39;</em> ist.</p><p>Bei einem Schließen des Fensters wird nachgefragt, ob die Eingaben gespeichert werden sollen.</p><h2 id="fachbezogene-fordermaßnahmen" tabindex="-1">Fachbezogene Fördermaßnahmen <a class="header-anchor" href="#fachbezogene-fordermaßnahmen" aria-label="Permalink to &quot;Fachbezogene Fördermaßnahmen&quot;">​</a></h2><p><a href="/bilder/schueler/foerdermassnahmen-fachbezogen-anlegen.png"><img src="'+m+'" alt="Anlegen einer fachbezogenen Fördermaßnahme über die Leistungsdaten des aktuellen Abschnitts." loading="lazy"></a></p><p><em>Anlegen einer fachbezogenen Fördermaßnahme über die Leistungsdaten des aktuellen Abschnitts.</em></p><p>Um eine Fachbezogene Fördermaßnahme anzulegen, ist auf dem Reiter <em>Schüler Leistungsdaten</em> mit der <em>rechten Maustaste</em> auf das betreffende Fach zu klicken.</p><p>Wählen Sie dort den Eintrag Fachbezogene Fördermaßnahme anlegen aus. Bestätigen Sie die anschließende Frage mit &quot;<strong>Ja</strong>&quot;.</p><p>Sie gelangen nun in den gleichen Bildschirm, der oben schon gezeigt wurde. Jedoch ist das Fach zur Fördermaßnahme schon eingetragen.</p>',25),e("div",{"data-hint-kind":"info",class:"info custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"info","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("circle",{cx:"12",cy:"12",r:"9"}),e("path",{d:"M12 11v6m0-10v.1"})]),n("Hinweis")]),e("p",null,[n("Bitte beachten Sie, dass jeder "),e("em",null,"eingetragene Fachlehrer"),n(" eine Fördermaßnahme anlegen kann. Allgemeine Fördermaßnahmen können nur "),e("em",null,"Klassenlehrer"),n(" oder "),e("em",null,"Abteilungsleiter"),n(" anlegen.")])],-1),a('<h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to &quot;Reporting&quot;">​</a></h2><p>Es gibt zwei Datenquellen, mit denen auf Fördermaßnahen in Reports zugegriffen werden kann.</p><ul><li><strong>Foerdermassnahmen</strong>:</li></ul><p>Diese Datenquelle stellt einen eigenen Bezug zu den Fördermaßnahmen her und ist nicht an die sonstigen Schülerdaten gekoppelt. Beim Aufruf dieser Datenquelle erscheint ein Auswahlfenster.</p><p>In diesem Fenster kann gewählt werden, aus welchen Lernabschnitten gedruckt werden soll. Die Auswahl filtert selbstständig alle Schüler, die in diesem Abschnitt eine Fördermaßnahme haben.</p><ul><li><strong>Datenquelle Schueler ➜ Lernabschnitte ➜ SchuelerFoerdermassnahmen</strong>:</li></ul><p>Diese Datenquelle verknüpft die Fördermaßnahmen mit den Schülerdaten. Gedruckt werden die Maßnahmen für den im Report-Explorer ausgewählten Lernabschnitt.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=F%C3%B6rderma%C3%9Fnahmen_(Sch%C3%BCler)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 3755.</p>',9)])])}const F=i(h,[["render",o]]);export{k as __pageData,F as default};
